<#
.SYNOPSIS
  QuroERP 저장소 안에서 Harness를 정리한다.
.DESCRIPTION
  Harness 문서 원본은 QuroHarness 저장소가 생성한다. 이 스크립트는 QuroERP 저장소 안에서 할 수 있는 일만 한다.
  -Mirror : .agents/skills 를 .claude/skills 로 복사한다 (직접 고친 .claude/skills 는 덮어쓴다)
  기본    : Mirror 후 validate-harness.ps1 실행
#>
param([switch]$Mirror)

$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
$src = Join-Path $root '.agents/skills'
$dst = Join-Path $root '.claude/skills'

if (Test-Path $dst) { Remove-Item $dst -Recurse -Force }
Copy-Item $src $dst -Recurse
Write-Host "미러링: .agents/skills → .claude/skills"

if (-not $Mirror) { & (Join-Path $PSScriptRoot 'validate-harness.ps1') -Root $root; exit $LASTEXITCODE }
